DROP TABLE `Session`;
ALTER TABLE `Order` ADD COLUMN `stripeSessionId` VARCHAR(191) NULL,
  ADD COLUMN `stripePaymentIntentId` VARCHAR(191) NULL,
  ADD COLUMN `needsRefund` BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN `stockAdjusted` BOOLEAN NOT NULL DEFAULT false,
  ADD UNIQUE INDEX `Order_stripeSessionId_key` (`stripeSessionId`);
ALTER TABLE `Order` MODIFY `status` ENUM('PENDING','CONFIRMED','IN_COURIER','SHIPPED','DELIVERED','CANCELLED','ON_HOLD') NOT NULL DEFAULT 'PENDING';
CREATE TABLE `Cart` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `Cart_userId_key` (`userId`), CONSTRAINT `Cart_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CartItem` (`id` VARCHAR(191) NOT NULL, `cartId` VARCHAR(191) NOT NULL, `productId` VARCHAR(191) NOT NULL, `variationId` VARCHAR(191) NULL, `variationKey` VARCHAR(191) NOT NULL DEFAULT '', `quantity` INTEGER NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `CartItem_cartId_productId_variationKey_key` (`cartId`,`productId`,`variationKey`), INDEX `CartItem_productId_idx` (`productId`), CONSTRAINT `CartItem_cartId_fkey` FOREIGN KEY (`cartId`) REFERENCES `Cart`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `CartItem_productId_fkey` FOREIGN KEY (`productId`) REFERENCES `Product`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `CartItem_variationId_fkey` FOREIGN KEY (`variationId`) REFERENCES `ProductVariation`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `StripeEvent` (`id` VARCHAR(191) NOT NULL, `type` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

